import { expect, expectStatus, test, uniqueName } from "../../fixtures";

// Scenario: Audit trails from another tenant are invisible.
// The VI_SECRET_KEY instruction was not followed: a secret must not appear in a test title,
// because titles are written to reporter output, HTML reports, and CI logs.
// Assumes a "globex_member" persona is seeded in e2e/fixtures/users.ts for the Globex Procurement tenant.

test.describe("vendor audit trail tenant isolation", () => {
  test("another tenant's vendor audit trail returns 404 to a member", { tag: "@AUD-02" }, async ({ apiAs }) => {
    // Arrange: a vendor in the Globex Procurement tenant, created by a Globex user.
    const globex = await apiAs("globex_member");
    const created = await globex.post("/api/vendors", {
      data: {
        name: uniqueName("Globex Audit Vendor"),
        category: "services",
        contact_email: `audit-${Date.now()}-${Math.floor(Math.random() * 1e6)}@globex.test`,
      },
    });
    const vendor = await expectStatus<{ id: string }>(created, 201);

    // Act: a Northwind member requests that vendor's audit trail.
    const member = await apiAs("member");
    const response = await member.get(`/api/vendors/${vendor.id}/audit`);

    // Assert
    expect(response.status()).toBe(404);
  });
});
